foreach (var t in asm.GetExportedTypes().OrderBy(x => x.FullName))
{
    var n = t.FullName ?? "";
    if (n.Contains("TestMethod") || n.Contains("Timeout") || n.Contains("Decorator"))
    {
        Console.WriteLine($"{n} | sealed={t.IsSealed} iface={t.IsInterface}");
        if (n.Contains("Decorator") || n.Contains("ITestMethod"))
        {
            foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
                Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
        }
    }
}
// Also check TestMethodAttribute members
var tma = typeof(Microsoft.VisualStudio.TestTools.UnitTesting.TestMethodAttribute);
Console.WriteLine($"\nTestMethodAttribute base: {tma.BaseType?.FullName}");
Console.WriteLine($"TestMethodAttribute sealed: {tma.IsSealed}");
foreach (var m in tma.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
    Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");

// Check for TestTimeout
foreach (var t in asm.GetExportedTypes())
{
    if (t.Name == "TestTimeout" || t.FullName?.Contains("TestTimeout") == true)
        Console.WriteLine($"\nFound: {t.FullName}");
}

// Check TimeoutAttribute
var ta = asm.GetExportedTypes().FirstOrDefault(t => t.Name == "TimeoutAttribute");
if (ta != null)
{
    Console.WriteLine($"\nTimeoutAttribute constructors:");
    foreach (var c in ta.GetConstructors())
        Console.WriteLine($"  ({string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
}
EOF
